async def act(page):
    import asyncio
    await asyncio.sleep(2)  # Ensure page is fully loaded

    # Get the main section
    main_section = page.get_by_role('main')

    # Look for rows or list items that might contain contributor data
    # Common roles in tables or lists: 'row', 'listitem', 'group'
    rows = main_section.get_by_role('row')
    row_count = await rows.count()

    if row_count > 0:
        max_commits = 0
        for i in range(row_count):
            row = rows.nth(i)
            text = await row.inner_text()
            # Extract numbers from the text
            import re
            numbers = re.findall(r'\b\d+\b', text)
            for num in numbers:
                try:
                    commits = int(num)
                    if commits > max_commits:
                        max_commits = commits
                except ValueError:
                    continue
        if max_commits > 0:
            return str(max_commits)

    # If no rows found, try list items
    list_items = main_section.get_by_role('listitem')
    item_count = await list_items.count()
    if item_count > 0:
        max_commits = 0
        for i in range(item_count):
            item = list_items.nth(i)
            text = await item.inner_text()
            import re
            numbers = re.findall(r'\b\d+\b', text)
            for num in numbers:
                try:
                    commits = int(num)
                    if commits > max_commits:
                        max_commits = commits
                except ValueError:
                    continue
        if max_commits > 0:
            return str(max_commits)

    # Fallback: extract all text from main section and find the highest number
    all_text = await main_section.inner_text()
    import re
    numbers = re.findall(r'\b\d+\b', all_text)
    max_commits = 0
    for num in numbers:
        try:
            commits = int(num)
            if commits > max_commits:
                max_commits = commits
        except ValueError:
            continue

    return str(max_commits) if max_commits > 0 else '0'

